    ('D01_realworld_python_release', 'finding-high', 'quiet', 'pipeline {\n  agent { docker { image \'python:3.12\' } }\n  environment { TWINE_NON_INTERACTIVE = \'1\' }\n  stages {\n    stage(\'Build\') {\n      steps {\n        sh \'python -m pip install build twine\'\n        sh \'python -m build\'\n      }\n    }\n    stage(\'Verify\') {\n      steps {\n        sh \'\'\'cd dist\nsha256sum -c ../SHA256SUMS || echo "WARNING: checksum mismatch"\ncd ..\n\'\'\'\n      }\n    }\n    stage(\'Publish\') {\n      when { buildingTag() }\n      steps {\n        withCredentials([string(credentialsId: \'pypi-token\', variable: \'TWINE_PASSWORD\')]) {\n          sh \'TWINE_USERNAME=__token__ twine upload dist/*\'\n        }\n      }\n    }\n  }\n  post {\n    always { archiveArtifacts artifacts: \'dist/*\', fingerprint: true }\n  }\n}\n'),
