    ('D03_realworld_scripted_finally_upload', 'finding-high', 'finding-high', "node('linux') {\n  checkout scm\n  try {\n    stage('Build') { sh './gradlew assemble' }\n    stage('Verify') { sh 'slsa-verifier verify-artifact build/libs/app.jar --provenance-path app.intoto.jsonl --source-uri github.com/acme/app' }\n  } finally {\n    stage('Upload') {\n      sh 'aws s3 cp build/libs/app.jar s3://acme-releases/app/'\n    }\n    junit 'build/test-results/**/*.xml'\n  }\n}\n"),
    ('D04_realworld_check_tee_log_then_deploy', 'finding-high', 'finding-high', "pipeline {\n  agent any\n  stages {\n    stage('Verify provenance') {\n      steps {\n        sh 'gh attestation verify dist/app.tar.gz --owner acme 2>&1 | tee attestation.log'\n      }\n    }\n    stage('Deploy') {\n      steps { sh 'gh release upload v1.0 dist/app.tar.gz' }\n    }\n  }\n}\n"),
