def verdict(text: str) -> str:
    result = jenkins.analyze("Jenkinsfile", textwrap.dedent(text).encode(), load(), None)
    severities = {f.severity for f in result.findings if f.rule == "OBAAF-JEN-011"}
    if severities:
        return "finding-high" if "high" in severities else "finding-medium"
    row = next((row for row in jenkins.coverage(result, result.findings) if row["rule"] == "OBAAF-JEN-011"), None)
    if row is None or row["status"] in ("pass", "not applicable"):
        return "quiet"
    return "unknown" if row["status"] == "unknown" else row["status"]


class FailurePathBypassTest(unittest.TestCase):
    def test_every_attempt(self):
        for name, expected, _before, text in CASES:
            with self.subTest(case=name):
                self.assertEqual(verdict(text), expected)

    def test_limits_name_real_cases_whose_answer_differs(self):
        answers = {c[0]: c[1] for c in CASES}
        self.assertLessEqual(set(LIMITS), set(answers))
        for name, (judged, _why) in LIMITS.items():
            self.assertNotEqual(answers[name], judged, name)

    def test_a_stated_limit_is_never_quiet_where_a_finding_was_judged(self):
        # Only the limits can differ from the judged answer (every other case is asserted above), so this says that no
        # stated limit lets a publish the reviewer judged a finding, or cannot tell, pass quietly. Four forms the Jenkins
        # model did not read before this slice either (LIMITS says why) are the exceptions; all four were quiet before.
        model_gaps = {"F37_post_failure_closure_via_parallel", "F38_post_always_publish_cmd_in_variable",
                      "R37_check_cmd_in_variable_or_true", "X10_script_conditional_return_skips_check"}
        answers = {c[0]: c[1] for c in CASES}
        for name, (judged, _why) in LIMITS.items():
            with self.subTest(case=name):
                if name not in model_gaps:
                    self.assertFalse(judged != "quiet" and answers[name] == "quiet")

    def test_no_attempt_is_slow(self):
        # The attacker's three slow inputs (P01 to P03) took 2.8 to 4.1 seconds before the slice.
        for name, _expected, _before, text in CASES:
            started = time.monotonic()
            verdict(text)
            with self.subTest(case=name):
                self.assertLess(time.monotonic() - started, 3.0)

    def test_old_messages_kept_for_a_baseline(self):
        # A Jenkins finding's message is its identity in a baseline: where the rule reported a case before the slice,
        # it words it as before.
        failure_path = ("pipeline {\n  agent any\n  stages {\n    stage('Build') { steps { sh 'make' } }\n  }\n"
                        "  post { always { sh 'twine upload dist/*' } }\n}\n")
        swallowed = ("node {\n  sh 'obaaf verify release --policy p.json --artifacts dist/a.tgz || true'\n"
                     "  sh 'twine upload dist/*'\n}\n")
        messages = []
        for text in (failure_path, swallowed):
            result = jenkins.analyze("Jenkinsfile", text.encode(), load(), None)
            messages += [f.message for f in result.findings if f.rule == "OBAAF-JEN-011"]
        self.assertEqual(messages, [
            "The step at line 6 publishes (twine upload) in post { always }, which runs when the build failed, was "
            "aborted or is unstable, so it can publish after a check failed or was skipped.",
            "The check at line 2 cannot stop the publish at line 3: its failure is ignored (|| or & after the command)."])


